package com.ruoyi.majorpilot.integration.ai;

import com.fasterxml.jackson.databind.*;
import com.ruoyi.majorpilot.content.*;
import com.ruoyi.majorpilot.experience.HintProvider;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.Flow;
import java.nio.ByteBuffer;
import java.io.ByteArrayOutputStream;
import org.junit.jupiter.api.Test;
import org.springframework.mock.env.MockEnvironment;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

class ExperienceHintTest {
    private static final ObjectMapper JSON=new ObjectMapper();
    private static final String ID="01JDEM00000000000000000001";
    private HintBailianGateway.Request request(){return new HintBailianGateway.Request(ID,"adjust",2,"先保存参数再运行。","范围决定参与计算的行。",JSON.createObjectNode().put("multiplier",2).put("include","ALL"));}
    private byte[] envelope(String output)throws Exception{return JSON.writeValueAsBytes(java.util.Map.of("choices",java.util.List.of(java.util.Map.of("finish_reason","stop","message",java.util.Map.of("content",output)))));}
    private TaskContentProvider content(){var repository=new TaskContentRepository(JSON);JsonNode m=repository.get("demo-table/1.0.0/manifest.json").manifest();var p=mock(TaskContentProvider.class);when(p.pinned(ID)).thenReturn(new TaskContent.Version(1,ID,"DEMO",null,"DEMO_TABLE","1.0.0","a".repeat(64),m));return p;}
    private HintProvider.Context context(){return new HintProvider.Context(ID,"1.0.0","adjust",2,"ignored",JSON.createObjectNode().set("input",JSON.createObjectNode().put("multiplier",2).put("include","ALL").put("email","not-forwarded@example.invalid")),"untrusted caller text",true);}
    @Test void actualAdapterSendsBusinessRequestAndValidatesReplyWithoutPaidCall()throws Exception{AtomicInteger calls=new AtomicInteger();byte[] response=envelope(HintBailianGateway.result(request(),"先比较范围变化，再查看行数。 ").toString());HintBailianGateway gateway=new HintBailianGateway("synthetic-unit-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(http,timeout)->{calls.incrementAndGet();assertEquals("https://dashscope.aliyuncs.com/compatible-mode/v1/chat/completions",http.uri().toString());assertTrue(timeout<=15000);return new BailianAiGateway.TransportResponse(200,response);},30000,ms->{});assertEquals("hint-result-v1",gateway.hint(request()).path("schemaVersion").asText());assertEquals(1,calls.get());}
    @Test void malformedOutputReceivesExactlyOneRepairThenStaticFallback()throws Exception{AtomicInteger calls=new AtomicInteger();byte[] response=envelope("{\"unexpected\":\"raw upstream private content\"}");HintBailianGateway gateway=new HintBailianGateway("synthetic-unit-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(http,t)->{calls.incrementAndGet();return new BailianAiGateway.TransportResponse(200,response);},30000,ms->{});var result=new ExperienceHintProvider(content(),gateway).hint(context());assertEquals(2,calls.get());assertEquals("FALLBACK",result.status());assertEquals("STATIC",result.provider());assertFalse(result.response().toString().contains("raw upstream"));assertFalse(result.response().toString().contains("untrusted caller"));}
    @Test void timeoutRateLimitAndAuthFailuresAreBoundedAndSanitized(){for(var code:new AiFailure.Code[]{AiFailure.Code.TIMEOUT,AiFailure.Code.RATE_LIMITED,AiFailure.Code.AUTH_FAILED}){AtomicInteger calls=new AtomicInteger();HintBailianGateway gateway=new HintBailianGateway("synthetic-unit-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(h,t)->{calls.incrementAndGet();throw new AiFailure(code);},30000,ms->{});assertEquals("FALLBACK",new ExperienceHintProvider(content(),gateway).hint(context()).status());assertEquals(code==AiFailure.Code.AUTH_FAILED?1:2,calls.get());}}
    @Test void existingBailianKeyAndP0ModeDoNotEnableLiveExperienceCalls(){MockEnvironment env=new MockEnvironment().withProperty("MAJORPILOT_AI_MODE","bailian").withProperty("BAILIAN_API_KEY","synthetic-unit-key");assertEquals("STATIC",new ExperienceHintProvider(content(),env).hint(context()).provider());env.withProperty("MP_EXPERIENCE_AI_ENABLED","false");assertEquals("STATIC",new ExperienceHintProvider(content(),env).hint(context()).provider());}
    @Test void providerOutputCannotChangeStepLevelOrAddHtmlLinksAndJudgments(){for(String text:new String[]{"https://example.invalid","<b>提示</b>","你的专业适合度很高","最终答案如下"})assertThrows(AiFailure.class,()->HintBailianGateway.result(request(),text));var out=HintBailianGateway.result(request(),"先查看范围字段。");out.put("hintLevel",3);assertThrows(AiFailure.class,()->HintBailianGateway.validateResult(request(),out));}
    @Test void unapprovedEndpointsNeverReceiveKeys(){for(String endpoint:new String[]{"http://dashscope.aliyuncs.com/compatible-mode/v1","https://example.invalid/compatible-mode/v1","https://dashscope.aliyuncs.com/compatible-mode/v1?key=bad"})assertThrows(AiFailure.class,()->new HintBailianGateway("unit-key",endpoint,"qwen3.7-plus"));}
    @Test void wireBodyContainsOnlyServerBuiltWhitelistedBusinessContext()throws Exception{byte[] response=envelope(HintBailianGateway.result(request(),"先比较所选范围。").toString());HintBailianGateway gateway=new HintBailianGateway("synthetic-unit-key",BailianAiGateway.DEFAULT_BASE_URL,BailianAiGateway.DEFAULT_MODEL,(http,t)->{try{JsonNode body=JSON.readTree(body(http));assertEquals(512,body.path("max_tokens").asInt());assertFalse(body.path("enable_thinking").asBoolean());assertFalse(body.path("stream").asBoolean());assertEquals("json_object",body.at("/response_format/type").asText());JsonNode context=JSON.readTree(body.at("/messages/1/content").asText());assertEquals(2,context.at("/input/multiplier").asInt());assertFalse(context.path("input").has("email"));assertFalse(context.toString().contains("untrusted caller text"));assertFalse(context.toString().contains("privateAssetKeys"));}catch(Exception e){throw new AssertionError(e);}return new BailianAiGateway.TransportResponse(200,response);},30000,ms->{});assertEquals("SUCCEEDED",new ExperienceHintProvider(content(),gateway).hint(context()).status());}
    private static byte[] body(java.net.http.HttpRequest request){ByteArrayOutputStream out=new ByteArrayOutputStream();request.bodyPublisher().orElseThrow().subscribe(new Flow.Subscriber<ByteBuffer>(){public void onSubscribe(Flow.Subscription subscription){subscription.request(Long.MAX_VALUE);}public void onNext(ByteBuffer buffer){byte[] bytes=new byte[buffer.remaining()];buffer.get(bytes);out.writeBytes(bytes);}public void onError(Throwable error){throw new AssertionError(error);}public void onComplete(){}});return out.toByteArray();}
}
